static string innerArr(const string& s){ if(s.size()>=2 && s.front()=='[' && s.back()==']') return s.substr(1,s.size()-2); return s; }
static vector<string> splitTop(const string& s){
    vector<string> parts; int depth=0,start=0;
    for(int i=0;i<(int)s.size();i++){
        if(s[i]=='['||s[i]=='{')depth++;
        else if(s[i]==']'||s[i]=='}')depth--;
